variants.ddl:
CREATE TABLE units (
  unit_id integer PRIMARY KEY,
  unit_name varchar(100) NOT NULL,
  base_location varchar(100),
  commander varchar(100)
);

CREATE TABLE officers (
  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name varchar(100) NOT NULL,
  rank varchar(50),
  unit_id integer NOT NULL REFERENCES units(unit_id),
  date_assigned date NOT NULL
);

CREATE TABLE logistics_units (
  logistics_unit_id integer PRIMARY KEY,
  logistics_unit_name varchar(100) NOT NULL,
  supplies_available integer,
  base_location varchar(100)
);

CREATE TABLE logistics_personnel (
  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name varchar(100) NOT NULL,
  position varchar(100),
  logistics_unit_id integer REFERENCES logistics_units(logistics_unit_id),
  date_assigned date
);

CREATE TABLE equipment (
  equipment_id integer PRIMARY KEY,
  equipment_type varchar(100) NOT NULL,
  condition varchar(50),
  last_inspection_date date
);

CREATE TABLE equipment_personnel (
  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name varchar(100) NOT NULL,
  role varchar(100),
  equipment_id integer REFERENCES equipment(equipment_id),
  assigned_unit varchar(100)
);

CREATE TABLE weapons (
  weapon_id integer PRIMARY KEY,
  weapon_type varchar(100) NOT NULL,
  ammunition_available integer,
  last_inspection_date date
);

CREATE TABLE weapons_personnel (
  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name varchar(100) NOT NULL,
  rank varchar(50),
  weapon_id integer REFERENCES weapons(weapon_id),
  assigned_unit varchar(100)
);

